{{--
    Chart Flexiwind : SVG et HTML rendus par Blade, sans librairie JavaScript.

    Le plugin resources/js/plugins/chart.js remplit l'infobulle au survol.
    `interactive` y ajoute le clavier et la légende cliquable.
    `brush` (qui implique `interactive`) permet de sélectionner une plage de
    catégories : le chart émet alors l'événement DOM `chart-range`.

    Sans contenu, le composant dessine un chart complet selon `type` :
    bar (avec `horizontal`), line, area, pie, donut ou radial.
    Avec contenu, il sert de cadre et chaque calque se pose dans la même
    cellule de grille, dans l'ordre d'écriture :

    <x-ui.chart :data="$data" :config="$config" index="month">
        <x-ui.chart.grid />
        <x-ui.chart.y-axis />
        <x-ui.chart.x-axis />
        <x-ui.chart.bar />
        <x-ui.chart.tooltip />
    </x-ui.chart>
--}}
@props([
    'data' => [],
    'config' => [],
    'index' => null,
    'type' => 'bar',
    'stacked' => false,
    'horizontal' => false,
    'min' => null,
    'max' => null,
    'format' => 'compact',
    'prefix' => '',
    'suffix' => '',
    'curve' => 'smooth',
    'label' => 'Chart',
    'legend' => null,
    'interactive' => false,
    'brush' => false,
])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    $hasData = $chart['count'] > 0 && $chart['series'] !== [];
    // Pie, donut et radial colorent les catégories : la légende les liste.
    $byCategory = in_array($type, ['pie', 'donut', 'radial'], true);
    $firstKey = $chart['series'][0]['key'] ?? null;
    $legendItems = $chart['series'];
    if ($byCategory) {
        $legendItems = [];
        foreach ($chart['palette'] as $i => $entry) {
            $legendItems[] = $entry + ['value' => $firstKey === null ? null : $chart['values'][$firstKey][$i]];
        }
    }
    $showLegend = $legend ?? count($legendItems) > 1;

    // Taille par défaut, sauf si la classe passée en donne une : sans
    // fusion de classes, `h-64` et `h-32` coexisteraient et l'ordre de la
    // feuille de style trancherait, pas l'intention.
    $userClass = (string) $attributes->get('class', '');
    $defaultSize = trim(
        (preg_match('/(^|\s)(h|size)-/', $userClass) ? '' : 'h-64 ')
        .(preg_match('/(^|\s)(w|size)-/', $userClass) ? '' : 'w-full')
    );
@endphp

@php
    // Pie, donut et radial n'ont pas de catégories à parcourir au clavier.
    $isInteractive = ((bool) $interactive || (bool) $brush) && $hasData;
    $canNavigate = $isInteractive && ! $byCategory;
    $hintId = $canNavigate ? 'chart-hint-'.substr(md5($label.serialize($chart['categories'])), 0, 8) : null;
@endphp

<figure data-slot="chart" aria-label="{{ $label }}"
    @if ($canNavigate) data-chart-interactive tabindex="0" aria-describedby="{{ $hintId }}" @endif
    @if ($canNavigate && $brush) data-chart-brush @endif
    {{ $attributes->class([
        'm-0 flex flex-col gap-4 '.$defaultSize,
        'rounded-ui outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-4 focus-visible:ring-offset-background' => $canNavigate,
    ]) }}>
    <div data-slot="chart-plot" class="grid min-h-0 flex-1 grid-cols-[auto_minmax(0,1fr)] grid-rows-[minmax(0,1fr)_auto]">
        @if (! $hasData)
            <p class="col-start-2 row-start-1 flex items-center justify-center rounded-ui border border-dashed border-border text-sm text-muted-foreground">
                No data to display
            </p>
        @elseif ($slot->isEmpty())
            @if ($type === 'pie' || $type === 'donut')
                <x-ui.chart.pie />
            @elseif ($type === 'radial')
                <x-ui.chart.radial />
            @else
                <x-ui.chart.grid />
                <x-ui.chart.y-axis />
                <x-ui.chart.x-axis />
                @if ($type === 'bar')
                    <x-ui.chart.bar />
                @else
                    <x-ui.chart.line :area="$type === 'area'" :curve="$curve" />
                @endif
                <x-ui.chart.tooltip />
            @endif
        @else
            {{ $slot }}
        @endif
    </div>

    @if ($hasData && $showLegend)
        <ul data-slot="chart-legend" @unless ($canNavigate) aria-hidden="true" @endunless class="flex flex-wrap items-center justify-center gap-x-4 gap-y-1.5 text-sm text-muted-foreground">
            @foreach ($legendItems as $item)
                <li class="flex items-center gap-1.5">
                    @if ($canNavigate)
                        {{-- Bouton : le plugin masque ou affiche la série. --}}
                        <button type="button" data-chart-toggle="{{ $item['key'] }}" aria-pressed="true"
                            class="flex cursor-pointer items-center gap-1.5 rounded-[calc(var(--radius-ui)-var(--spacing))] px-1 py-0.5 transition-opacity hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:outline-none aria-[pressed=false]:opacity-40 aria-[pressed=false]:line-through">
                            <span class="size-2.5 shrink-0 rounded-[3px]" style="background: {{ $item['color'] }}"></span>
                            {{ $item['label'] }}
                        </button>
                    @else
                        <span class="size-2.5 shrink-0 rounded-[3px]" style="background: {{ $item['color'] }}"></span>
                        {{ $item['label'] }}
                        @if ($byCategory && ($item['value'] ?? null) !== null)
                            <span class="font-medium text-foreground tabular-nums">{{ \App\Flexiwind\ChartHelper::format($item['value'], $format, $prefix, $suffix) }}</span>
                        @endif
                    @endif
                </li>
            @endforeach
        </ul>
    @endif

    @if ($canNavigate)
        <p id="{{ $hintId }}" class="sr-only">
            Use the arrow keys to read each value.@if ($brush) Hold Shift with the arrow keys to select a range, then press Enter.@endif
        </p>
        <p data-chart-live aria-live="polite" class="sr-only"></p>
    @endif

    @if ($hasData)
        {{-- Les calques visuels sont masqués aux lecteurs d'écran : ils lisent ce tableau. --}}
        {{-- sr-only sur un div : un <table> ignore height et overflow, il agrandirait la page. --}}
        <div class="sr-only">
            <table>
                <caption>{{ $label }}</caption>
                <thead>
                    <tr>
                        <th scope="col">{{ $index ? ucfirst($index) : 'Category' }}</th>
                        @foreach ($chart['series'] as $series)
                            <th scope="col">{{ $series['label'] }}</th>
                        @endforeach
                    </tr>
                </thead>
                <tbody>
                    @foreach ($chart['categories'] as $i => $category)
                        <tr>
                            <th scope="row">{{ $category }}</th>
                            @foreach ($chart['series'] as $series)
                                <td data-value="{{ $chart['values'][$series['key']][$i] }}">{{ \App\Flexiwind\ChartHelper::format($chart['values'][$series['key']][$i], $format, $prefix, $suffix) }}</td>
                            @endforeach
                        </tr>
                    @endforeach
                </tbody>
            </table>
        </div>
    @endif
</figure>

{{-- Lignes horizontales aux graduations. La ligne du zéro reste pleine quand l'échelle descend sous zéro. --}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])
@props(['vertical' => false])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    $scale = $chart['scale'];
    $layout = $type === 'bar' ? 'band' : 'point';
@endphp

<div data-slot="chart-grid" aria-hidden="true" {{ $attributes->class('pointer-events-none relative col-start-2 row-start-1') }}>
    @foreach ($scale['ticks'] as $tick)
        @php $isZero = $tick == 0 && $scale['min'] < 0; @endphp
        @if ($horizontal)
            <span @class(['absolute inset-y-0 border-l', 'border-border-strong' => $isZero, 'border-dashed border-border' => ! $isZero])
                style="left: {{ \App\Flexiwind\ChartHelper::position($tick, $scale) }}%"></span>
        @else
            <span @class(['absolute inset-x-0 border-t', 'border-border-strong' => $isZero, 'border-dashed border-border' => ! $isZero])
                style="top: {{ \App\Flexiwind\ChartHelper::y($tick, $scale) }}%"></span>
        @endif
    @endforeach
    @if ($vertical && ! $horizontal)
        @for ($i = 0; $i < $chart['count']; $i++)
            <span class="absolute inset-y-0 border-l border-dashed border-border" style="left: {{ \App\Flexiwind\ChartHelper::x($i, $chart['count'], $layout) }}%"></span>
        @endfor
    @endif
</div>

{{--
    Graduations de l'axe vertical. La colonne prend la largeur du plus long
    libellé grâce à des copies invisibles dans le flux : rien à régler.
--}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    // Horizontal : l'axe vertical porte les catégories, pas les valeurs.
    $ticks = $horizontal
        ? array_map(fn (string $category, int $i): array => [
            'label' => $category,
            'top' => \App\Flexiwind\ChartHelper::x($i, $chart['count'], 'band'),
        ], $chart['categories'], array_keys($chart['categories']))
        : array_map(fn (float $tick): array => [
            'label' => \App\Flexiwind\ChartHelper::format($tick, $format, $prefix, $suffix),
            'top' => \App\Flexiwind\ChartHelper::y($tick, $chart['scale']),
        ], $chart['scale']['ticks']);
@endphp

<div data-slot="chart-y-axis" aria-hidden="true" {{ $attributes->class('relative col-start-1 row-start-1 pr-3 text-xs leading-none text-muted-foreground tabular-nums') }}>
    @foreach ($ticks as $tick)
        <span class="invisible block h-0 max-w-32 truncate whitespace-nowrap">{{ $tick['label'] }}</span>
    @endforeach
    @foreach ($ticks as $tick)
        <span class="absolute right-3 max-w-32 -translate-y-1/2 truncate whitespace-nowrap" style="top: {{ $tick['top'] }}%">{{ $tick['label'] }}</span>
    @endforeach
</div>

{{-- Libellés des catégories. `interval` n'en garde qu'un sur N ; par défaut, au plus 12 libellés. --}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])
@props(['interval' => null])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    $count = $chart['count'];
    $layout = $type === 'bar' ? 'band' : 'point';
    $every = max(1, (int) ($interval ?? ceil($count / 12)));
@endphp

<div data-slot="chart-x-axis" aria-hidden="true" {{ $attributes->class('relative col-start-2 row-start-2 mt-2.5 h-4 text-xs leading-none text-muted-foreground') }}>
    @if ($horizontal)
        @foreach ($chart['scale']['ticks'] as $tick)
            <span class="absolute top-0 -translate-x-1/2 whitespace-nowrap tabular-nums"
                style="left: {{ \App\Flexiwind\ChartHelper::position($tick, $chart['scale']) }}%">{{ \App\Flexiwind\ChartHelper::format($tick, $format, $prefix, $suffix) }}</span>
        @endforeach
    @else
        @foreach ($chart['categories'] as $i => $category)
            @continue($i % $every !== 0)
            <span @class([
                'absolute top-0 max-w-24 truncate whitespace-nowrap',
                '-translate-x-1/2' => $layout === 'band' || ($i > 0 && $i < $count - 1),
                '-translate-x-full' => $layout === 'point' && $i === $count - 1 && $count > 1,
            ]) style="left: {{ \App\Flexiwind\ChartHelper::x($i, $count, $layout) }}%">{{ $category }}</span>
        @endforeach
    @endif
</div>

{{--
    Barres groupées, ou empilées avec `stacked` sur la racine ; couchées avec `horizontal`.
    `only` limite le calque à certaines séries (barres + ligne dans un même chart).
--}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])
@props(['radius' => 4, 'gap' => 0.3, 'only' => null])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    if ($only !== null) {
        $keys = (array) $only;
        $chart['series'] = array_values(array_filter($chart['series'], fn (array $s): bool => in_array($s['key'], $keys, true)));
    }
    $r = max(0, (int) $radius);
@endphp

<div data-slot="chart-bars" aria-hidden="true"
    @if ($stacked) data-stacked data-scale-min="{{ $chart['scale']['min'] }}" data-scale-max="{{ $chart['scale']['max'] }}" data-radius="{{ $r }}" @endif
    @if ($horizontal) data-horizontal @endif
    {{ $attributes->class('pointer-events-none relative col-start-2 row-start-1') }}>
    @foreach (\App\Flexiwind\ChartHelper::bars($chart, (float) $gap, (bool) $horizontal) as $bar)
        <span data-series="{{ $bar['key'] }}" data-index="{{ $bar['index'] }}" data-value="{{ $bar['value'] }}" class="absolute transition-[top,left,width,height] duration-500 ease-out"
            style="left: {{ $bar['left'] }}%; width: {{ $bar['width'] }}%; top: {{ $bar['top'] }}%; height: {{ $bar['height'] }}%; background: {{ $bar['color'] }}; border-radius: {{ match ($bar['end']) { 'top' => "{$r}px {$r}px 0 0", 'bottom' => "0 0 {$r}px {$r}px", 'right' => "0 {$r}px {$r}px 0", 'left' => "{$r}px 0 0 {$r}px", default => '0' } }}"></span>
    @endforeach
</div>

{{--
    Lignes, ou aires avec `area`. Le tracé vit dans une viewBox 0 0 100 100
    étirée : le trait garde son épaisseur grâce à vector-effect, et les
    points sont des éléments HTML pour rester ronds.
--}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])
@props(['curve' => 'smooth', 'area' => false, 'dots' => null, 'strokeWidth' => 2, 'only' => null])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    $series = $only === null
        ? $chart['series']
        : array_values(array_filter($chart['series'], fn (array $s): bool => in_array($s['key'], (array) $only, true)));
    $layout = $type === 'bar' ? 'band' : 'point';
    $smooth = $curve !== 'linear';
    $showDots = $dots ?? $chart['count'] <= 16;
    $uid = 'fx-chart-'.substr(md5(serialize([$data, $series])), 0, 8);
@endphp

<div data-slot="chart-lines" aria-hidden="true" {{ $attributes->class('pointer-events-none relative col-start-2 row-start-1') }}>
    <svg class="absolute inset-0 size-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
        @if ($area)
            <defs>
                @foreach ($series as $item)
                    <linearGradient id="{{ $uid }}-{{ $loop->index }}" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" style="stop-color: {{ $item['color'] }}; stop-opacity: 0.32"></stop>
                        <stop offset="100%" style="stop-color: {{ $item['color'] }}; stop-opacity: 0.02"></stop>
                    </linearGradient>
                @endforeach
            </defs>
            @foreach ($series as $item)
                <path data-series="{{ $item['key'] }}" d="{{ \App\Flexiwind\ChartHelper::path($chart, $item['key'], $layout, $smooth, true) }}" fill="url(#{{ $uid }}-{{ $loop->index }})"></path>
            @endforeach
        @endif
        @foreach ($series as $item)
            <path data-series="{{ $item['key'] }}" d="{{ \App\Flexiwind\ChartHelper::path($chart, $item['key'], $layout, $smooth) }}" fill="none"
                vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"
                style="stroke: {{ $item['color'] }}; stroke-width: {{ (float) $strokeWidth }}px"></path>
        @endforeach
    </svg>

    @if ($showDots)
        @foreach ($series as $item)
            @foreach ($chart['values'][$item['key']] as $i => $value)
                @continue($value === null)
                <span data-series="{{ $item['key'] }}" class="absolute size-2 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-background"
                    style="left: {{ \App\Flexiwind\ChartHelper::x($i, $chart['count'], $layout) }}%; top: {{ \App\Flexiwind\ChartHelper::y($value, $chart['scale']) }}%; background: {{ $item['color'] }}"></span>
            @endforeach
        @endforeach
    @endif
</div>

{{--
    Infobulle : un seul panneau par chart, quel que soit le nombre de
    catégories. Le plugin resources/js/plugins/chart.js trouve la catégorie
    sous le pointeur, lit ses valeurs dans le tableau de données du chart et
    remplit le panneau. Posez ce calque en dernier : il reçoit le survol.
--}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'horizontal' => false, 'brush' => false])
@props(['cursor' => true])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, (bool) $stacked, $min, $max);
    $layout = $type === 'bar' || $horizontal ? 'band' : 'point';
@endphp

<div data-slot="chart-tooltip" aria-hidden="true"
    data-count="{{ $chart['count'] }}" data-layout="{{ $layout }}" data-scale-min="{{ $chart['scale']['min'] }}" data-scale-max="{{ $chart['scale']['max'] }}"
    @if ($horizontal) data-horizontal @endif
    @if ($cursor) data-cursor @endif
    {{ $attributes->class([
        'group/tooltip relative z-10 col-start-2 row-start-1',
        // Glisser horizontalement sélectionne ; le défilement vertical reste au navigateur.
        'cursor-crosshair touch-pan-y select-none' => $brush,
    ]) }}>
    @if ($brush)
        <div data-chart-brush-overlay hidden @class([
            'pointer-events-none absolute rounded-[calc(var(--radius-ui)-var(--spacing)*0.5)] bg-primary/12 ring-1 ring-primary/50 ring-inset',
            'inset-x-0' => $horizontal,
            'inset-y-0' => ! $horizontal,
        ])></div>
    @endif

    @if ($cursor)
        <span data-chart-cursor @class([
            'pointer-events-none absolute opacity-0 transition-opacity group-data-open/tooltip:opacity-100',
            'inset-x-0 rounded-[calc(var(--radius-ui)-var(--spacing)*0.5)] bg-foreground/5' => $layout === 'band' && $horizontal,
            'inset-y-0 rounded-[calc(var(--radius-ui)-var(--spacing)*0.5)] bg-foreground/5' => $layout === 'band' && ! $horizontal,
            'inset-y-0 w-px bg-border-strong' => $layout === 'point',
        ])></span>
        @if ($layout === 'point')
            @foreach ($chart['series'] as $item)
                <span data-chart-dot data-series="{{ $item['key'] }}"
                    class="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-background opacity-0 shadow-sm transition-opacity group-data-open/tooltip:opacity-100"
                    style="background: {{ $item['color'] }}"></span>
            @endforeach
        @endif
    @endif

    <div data-chart-panel @class([
        'pointer-events-none invisible absolute min-w-36 rounded-ui border border-border bg-background px-3 py-2 text-xs opacity-0 shadow-lg transition-opacity group-data-open/tooltip:visible group-data-open/tooltip:opacity-100',
        '-translate-y-1/2' => $horizontal,
        'top-1' => ! $horizontal,
    ])>
        <p data-chart-title class="mb-1.5 font-medium whitespace-nowrap text-foreground"></p>
        <ul class="flex flex-col gap-1">
            @foreach ($chart['series'] as $item)
                <li data-series="{{ $item['key'] }}" class="flex items-center justify-between gap-4 whitespace-nowrap">
                    <span class="flex items-center gap-1.5 text-muted-foreground">
                        <span class="size-2 rounded-[2px]" style="background: {{ $item['color'] }}"></span>
                        {{ $item['label'] }}
                    </span>
                    <span data-chart-value class="font-mono font-medium text-foreground tabular-nums"></span>
                </li>
            @endforeach
        </ul>
    </div>
</div>

{{--
    Pie, ou donut avec `inner` (rayon intérieur, 0 à 0.9). Une part par
    catégorie, colorée par `config` sur le nom de la catégorie. Le slot remplit
    le centre d'un donut ; sans slot, il affiche le total.
--}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])
@props(['inner' => null, 'series' => null, 'centerLabel' => 'Total'])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, false, null, null);
    $radius = (float) ($inner ?? ($type === 'donut' ? 0.62 : 0));
    $slices = \App\Flexiwind\ChartHelper::slices($chart, $series, $radius);
    $total = array_sum(array_column($slices, 'value'));
@endphp

<div data-slot="chart-pie" {{ $attributes->class('relative col-span-2 col-start-1 row-span-2 row-start-1 flex min-h-0 items-center justify-center') }}>
    <div class="relative aspect-square h-full max-w-full">
        <svg viewBox="-1.02 -1.02 2.04 2.04" aria-hidden="true" class="group/pie size-full overflow-visible">
            @foreach ($slices as $slice)
                <path d="{{ $slice['path'] }}" stroke-width="0.02" stroke-linejoin="round"
                    class="stroke-background transition-opacity duration-200 group-hover/pie:not-hover:opacity-35"
                    style="fill: {{ $slice['color'] }}">
                    <title>{{ $slice['label'] }}: {{ \App\Flexiwind\ChartHelper::format($slice['value'], $format, $prefix, $suffix) }} ({{ $slice['percent'] }}%)</title>
                </path>
            @endforeach
        </svg>

        @if ($radius > 0)
            <div class="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
                @if ($slot->isNotEmpty())
                    {{ $slot }}
                @else
                    <span class="text-2xl font-semibold tracking-tight text-foreground tabular-nums">{{ \App\Flexiwind\ChartHelper::format($total, $format, $prefix, $suffix) }}</span>
                    <span class="text-xs text-muted-foreground">{{ $centerLabel }}</span>
                @endif
            </div>
        @endif
    </div>
</div>

{{--
    Anneaux de progression : une catégorie par anneau, de l'extérieur vers
    l'intérieur. La valeur se lit sur `max` (100 par défaut). `half` en
    fait une jauge en demi-cercle. Le slot remplit le centre.
--}}
@aware(['data' => [], 'config' => [], 'index' => null, 'type' => 'bar', 'stacked' => false, 'min' => null, 'max' => null, 'format' => 'compact', 'prefix' => '', 'suffix' => '', 'horizontal' => false])
@props(['thickness' => 0.14, 'gap' => 0.05, 'half' => false, 'series' => null, 'track' => true])

@php
    $chart = \App\Flexiwind\ChartHelper::make($data, $config, $index, false, null, null);
    $thick = min(0.5, max(0.02, (float) $thickness));
    $rings = \App\Flexiwind\ChartHelper::rings($chart, is_numeric($max) ? (float) $max : 100.0, $thick, (float) $gap, $series);
    $first = $rings[0] ?? null;
@endphp

<div data-slot="chart-radial" {{ $attributes->class('relative col-span-2 col-start-1 row-span-2 row-start-1 flex min-h-0 items-center justify-center') }}>
    <div @class(['relative h-full max-w-full', 'aspect-square' => ! $half, 'aspect-[2/1.08]' => $half])>
        <svg viewBox="{{ $half ? '-1 -1 2 1.08' : '-1 -1 2 2' }}" aria-hidden="true" class="size-full overflow-visible">
            @foreach ($rings as $ring)
                @if ($track)
                    <circle r="{{ $ring['radius'] }}" cx="0" cy="0" fill="none" pathLength="100" stroke-width="{{ $thick }}"
                        stroke-dasharray="{{ $half ? '50 100' : '100 0' }}" transform="rotate({{ $half ? 180 : -90 }})" stroke-linecap="round"
                        style="stroke: color-mix(in oklab, {{ $ring['color'] }} 16%, transparent)"></circle>
                @endif
                @if ($ring['percent'] > 0)
                    <circle r="{{ $ring['radius'] }}" cx="0" cy="0" fill="none" pathLength="100" stroke-width="{{ $thick }}"
                        stroke-dasharray="{{ $half ? $ring['percent'] / 2 : $ring['percent'] }} 100" transform="rotate({{ $half ? 180 : -90 }})" stroke-linecap="round"
                        class="transition-[stroke-dasharray] duration-700 ease-out" style="stroke: {{ $ring['color'] }}">
                        <title>{{ $ring['label'] }}: {{ \App\Flexiwind\ChartHelper::format($ring['value'], $format, $prefix, $suffix) }}</title>
                    </circle>
                @endif
            @endforeach
        </svg>

        <div @class(['pointer-events-none absolute inset-0 flex flex-col items-center text-center', 'justify-center' => ! $half, 'justify-end pb-1' => $half])>
            @if ($slot->isNotEmpty())
                {{ $slot }}
            @elseif (count($rings) === 1 && $first)
                <span class="text-2xl font-semibold tracking-tight text-foreground tabular-nums">{{ \App\Flexiwind\ChartHelper::format($first['value'], $format, $prefix, $suffix) }}</span>
                <span class="text-xs text-muted-foreground">{{ $first['label'] }}</span>
            @endif
        </div>
    </div>
</div>

/**
 * Comportement des charts Flexiwind.
 *
 * Le chart est dessiné par Blade ; ce fichier ajoute ce que le HTML seul ne
 * peut pas faire. Sur tous les charts en barres, lignes ou aires :
 *
 *  - l'infobulle : un seul panneau par chart, rempli au survol à partir du
 *    tableau de données (celui des lecteurs d'écran). Le DOM ne grossit pas
 *    avec le nombre de catégories ;
 *  - le toucher : taper une catégorie affiche son infobulle.
 *
 * Et sur les charts marqués `interactive` :
 *
 *  - le clavier : flèches, Début, Fin, Échap, avec annonce vocale ;
 *  - la légende cliquable : masquer ou afficher une série ;
 *  - l'export CSV : `data-chart-export` sur n'importe quel bouton ;
 *  - la sélection d'une plage (`brush`) : glisser, ou Maj + flèches puis
 *    Entrée. Le chart émet `chart-range` avec { start, end, from, to } ;
 *    un double-clic émet la même chose à null, pour revenir en arrière.
 *
 * Tout passe par des écouteurs délégués sur le document : rien à
 * initialiser par chart, et un chart remplacé par Livewire fonctionne
 * aussitôt.
 */

const CHART = '[data-slot="chart"]';
const INTERACTIVE = "[data-chart-interactive]";
const LAYER = '[data-slot="chart-tooltip"]';
const BRUSH = "[data-chart-brush]";

let started = false;

/** Glisser en cours : { chart, anchor, current, pointerId, moved }. */
let drag = null;

/** Le calque survolé par la souris, pour le refermer en sortant. */
let hovered = null;

/** Branche les écouteurs une seule fois, quel que soit le nombre d'appels. */
export function initChartInteractions(root = document) {
    if (started) {
        return;
    }

    started = true;
    root.addEventListener("keydown", onKeydown);
    root.addEventListener("pointerdown", onPointerDown);
    root.addEventListener("pointermove", onPointerMove);
    root.addEventListener("pointerup", onPointerUp);
    root.addEventListener("pointercancel", () => (drag = null));
    root.addEventListener("pointerout", onPointerOut);
    root.addEventListener("focusout", onFocusOut);
    root.addEventListener("click", onClick);
    root.addEventListener("dblclick", onDoubleClick);
}

/** Forme plugin Alpine, comme les autres plugins Flexiwind. */
export function ChartPlugin() {
    initChartInteractions();
}

// ------------------------------------------------------------- géométrie

/** Ce que Blade a écrit sur le calque : même calcul que ChartHelper. */
function geometry(layer) {
    return {
        count: Number(layer.dataset.count) || 0,
        point: layer.dataset.layout === "point",
        horizontal: layer.hasAttribute("data-horizontal"),
        min: Number(layer.dataset.scaleMin),
        max: Number(layer.dataset.scaleMax),
    };
}

/** Centre d'une catégorie, en % (ChartHelper::x). */
function center(index, { count, point }) {
    if (point) {
        return count <= 1 ? 50 : (index / (count - 1)) * 100;
    }

    return ((index + 0.5) / Math.max(1, count)) * 100;
}

/** La tranche d'une catégorie, en % (ChartHelper::slot). */
function slot(index, g) {
    if (g.point && g.count > 1) {
        const width = 100 / (g.count - 1);
        const left = Math.max(0, center(index, g) - width / 2);
        const right = Math.min(100, center(index, g) + width / 2);

        return { left, width: right - left };
    }

    const width = 100 / Math.max(1, g.count);

    return { left: index * width, width };
}

/** Position d'une valeur sur l'axe des valeurs, en % depuis le bas ou la gauche. */
const along = (value, { min, max }) => ((value - min) / (max - min || 1)) * 100;

/** La catégorie sous le pointeur ; au-delà des bords, la première ou la dernière. */
function indexAt(layer, x, y) {
    const g = geometry(layer);
    const rect = layer.getBoundingClientRect();
    const size = g.horizontal ? rect.height : rect.width;
    const ratio = Math.min(1, Math.max(0, ((g.horizontal ? y - rect.top : x - rect.left) / (size || 1))));

    if (g.point && g.count > 1) {
        return Math.round(ratio * (g.count - 1));
    }

    return Math.min(g.count - 1, Math.floor(ratio * g.count));
}

// -------------------------------------------------------------- infobulle

const layerOf = (chart) => chart?.querySelector(LAYER) ?? null;

const rowsOf = (chart) => [...(chart?.querySelector("table")?.tBodies[0]?.rows ?? [])];

const countOf = (chart) => {
    const layer = layerOf(chart);

    return layer ? geometry(layer).count : 0;
};

/** Le libellé d'une catégorie, lu dans le tableau de données. */
const categoryOf = (chart, index) => rowsOf(chart)[index]?.cells[0]?.textContent.trim() ?? null;

/**
 * Affiche l'infobulle de la catégorie `index`, ou la ferme (null). Les
 * valeurs viennent du tableau de données, déjà mises en forme par Blade ;
 * textContent seulement : rien n'est interprété comme du HTML.
 */
function show(layer, index) {
    const chart = layer.closest(CHART);
    const row = index === null ? null : rowsOf(chart)[index];

    if (!row) {
        layer.removeAttribute("data-open");
        delete layer.dataset.index;

        return;
    }

    if (layer.dataset.index === String(index)) {
        return;
    }

    const g = geometry(layer);
    const zone = slot(index, g);
    const middle = center(index, g);
    const cells = [...row.cells].slice(1);
    const raw = cells.map((cell) => (cell.dataset.value === "" ? null : Number(cell.dataset.value)));

    layer.dataset.index = String(index);

    const panel = layer.querySelector("[data-chart-panel]");
    panel.querySelector("[data-chart-title]").textContent = row.cells[0].textContent.trim();
    panel.querySelectorAll("li").forEach((item, i) => {
        item.querySelector("[data-chart-value]").textContent = cells[i]?.textContent.trim() ?? "";
    });

    const cursor = layer.querySelector("[data-chart-cursor]");

    if (cursor && g.point) {
        cursor.style.left = `${middle}%`;
    } else if (cursor) {
        // Le fond de la catégorie, en retrait de 6 % de chaque côté.
        cursor.style[g.horizontal ? "top" : "left"] = `${zone.left + zone.width * 0.06}%`;
        cursor.style[g.horizontal ? "height" : "width"] = `${zone.width * 0.88}%`;
    }

    layer.querySelectorAll("[data-chart-dot]").forEach((dot, i) => {
        dot.hidden = raw[i] === null || raw[i] === undefined;
        dot.style.left = `${middle}%`;
        dot.style.top = `${100 - along(raw[i] ?? 0, g)}%`;
    });

    panel.style.left = panel.style.right = panel.style.top = "";

    if (g.horizontal) {
        // Au bout de la plus longue barre, ou à sa gauche si elle est trop longue.
        const reach = Math.max(0, ...raw.filter((value) => value !== null).map((value) => along(value, g)));

        panel.style.top = `${middle}%`;
        panel.style[reach < 60 ? "left" : "right"] = reach < 60 ? `calc(${reach}% + 12px)` : `calc(${100 - reach}% + 12px)`;
    } else if (index < g.count / 2) {
        panel.style.left = `calc(${middle}% + 12px)`;
    } else {
        panel.style.right = `calc(${100 - middle}% + 12px)`;
    }

    layer.setAttribute("data-open", "");
}

// ---------------------------------------------------------------- état

const activeIndex = (chart) => {
    const value = chart.dataset.chartActive;

    return value === undefined || value === "" ? null : Number(value);
};

/** La catégorie choisie au clavier ou au toucher ; elle reste affichée. */
function setActive(chart, index) {
    chart.dataset.chartActive = index === null ? "" : String(index);

    const layer = layerOf(chart);

    if (layer) {
        show(layer, index);
    }

    const live = chart.querySelector("[data-chart-live]");

    if (live) {
        const panel = index === null ? null : layer?.querySelector("[data-chart-panel]");

        live.textContent = panel ? readable(panel) : "";
    }
}

/** Le texte du panneau, sans les séries masquées, sur une ligne. */
function readable(panel) {
    const title = panel.querySelector("[data-chart-title]")?.textContent.trim() ?? "";
    const rows = [...panel.querySelectorAll("li")]
        .filter((row) => row.style.display !== "none")
        .map((row) => row.textContent.replace(/\s+/g, " ").trim());

    return [title, ...rows].join(". ");
}

// ------------------------------------------------------------ événements

function onKeydown(event) {
    const chart = event.target.closest?.(INTERACTIVE);

    // Seulement quand le chart lui-même a le focus : pas les boutons de légende.
    if (!chart || event.target !== chart) {
        return;
    }

    const count = countOf(chart);
    const current = activeIndex(chart);

    if (count === 0) {
        return;
    }

    const moves = {
        ArrowRight: 1,
        ArrowDown: 1,
        ArrowLeft: -1,
        ArrowUp: -1,
    };

    const brush = chart.matches(BRUSH);

    if (brush && event.key === "Enter" && chart.dataset.chartSelection) {
        event.preventDefault();
        const [low, high] = chart.dataset.chartSelection.split(":").map(Number);
        commit(chart, low, high);

        return;
    }

    if (brush && event.key === "Escape" && chart.dataset.chartSelection) {
        event.preventDefault();
        select(chart, null);

        return;
    }

    let next;

    if (event.key in moves) {
        next = current === null ? 0 : Math.min(count - 1, Math.max(0, current + moves[event.key]));
    } else if (event.key === "Home") {
        next = 0;
    } else if (event.key === "End") {
        next = count - 1;
    } else if (event.key === "Escape" && current !== null) {
        next = null;
    } else {
        return;
    }

    event.preventDefault();

    if (brush && event.shiftKey && event.key in moves) {
        chart.dataset.chartAnchor ??= String(current ?? 0);
        select(chart, Number(chart.dataset.chartAnchor), next);
    } else if (event.key in moves || event.key === "Home" || event.key === "End") {
        delete chart.dataset.chartAnchor;
    }

    setActive(chart, next);
}

function onPointerDown(event) {
    const layer = event.target.closest?.(LAYER) ?? null;
    const brushed = layer?.closest(BRUSH);

    if (brushed && (event.pointerType !== "mouse" || event.button === 0)) {
        const index = indexAt(layer, event.clientX, event.clientY);

        drag = { chart: brushed, anchor: index, current: index, pointerId: event.pointerId, moved: false };

        if (event.pointerType === "mouse") {
            // Pas de sélection de texte pendant le glisser.
            event.preventDefault();
        }
    }

    // La souris a le survol : on ne gère ici que le doigt et le stylet.
    if (event.pointerType === "mouse") {
        return;
    }

    const touched = layer?.closest(CHART) ?? null;

    document.querySelectorAll(CHART).forEach((chart) => {
        if (chart !== touched && activeIndex(chart) !== null) {
            setActive(chart, null);
        }
    });

    if (touched) {
        setActive(touched, indexAt(layer, event.clientX, event.clientY));
    }
}

function onPointerMove(event) {
    if (drag && event.pointerId === drag.pointerId) {
        const index = indexAt(layerOf(drag.chart), event.clientX, event.clientY);

        if (index !== drag.current) {
            drag.current = index;
            drag.moved = true;
            select(drag.chart, drag.anchor, index);
        }
    }

    if (event.pointerType !== "mouse") {
        return;
    }

    const layer = event.target.closest?.(LAYER) ?? null;

    if (hovered && hovered !== layer) {
        leave();
    }

    if (layer) {
        hovered = layer;
        show(layer, indexAt(layer, event.clientX, event.clientY));
    }
}

function onPointerOut(event) {
    if (hovered && event.pointerType === "mouse" && !hovered.contains(event.relatedTarget)) {
        leave();
    }
}

/** La souris quitte le chart : on revient à la catégorie du clavier, s'il y en a une. */
function leave() {
    const chart = hovered.closest(CHART);

    show(hovered, chart ? activeIndex(chart) : null);
    hovered = null;
}

function onPointerUp(event) {
    if (!drag || event.pointerId !== drag.pointerId) {
        return;
    }

    const { chart, anchor, current, moved } = drag;

    drag = null;

    // Un simple clic n'est pas une sélection : il faut au moins deux catégories.
    if (moved && anchor !== current) {
        commit(chart, Math.min(anchor, current), Math.max(anchor, current));
    }
}

function onDoubleClick(event) {
    const chart = event.target.closest?.(LAYER)?.closest(BRUSH);

    if (!chart) {
        return;
    }

    select(chart, null);
    chart.dispatchEvent(
        new CustomEvent("chart-range", {
            bubbles: true,
            detail: { start: null, end: null, from: null, to: null },
        }),
    );
}

/** Dessine la sélection de `from` à `to` (dans un sens ou l'autre), ou l'efface. */
function select(chart, from, to = from) {
    const overlay = chart.querySelector("[data-chart-brush-overlay]");

    if (!overlay) {
        return;
    }

    if (from === null) {
        overlay.hidden = true;
        delete chart.dataset.chartSelection;
        delete chart.dataset.chartAnchor;

        return;
    }

    const g = geometry(layerOf(chart));
    const low = Math.min(from, to);
    const high = Math.max(from, to);
    const start = slot(low, g).left;
    const end = slot(high, g).left + slot(high, g).width;

    overlay.style[g.horizontal ? "top" : "left"] = `${start}%`;
    overlay.style[g.horizontal ? "height" : "width"] = `${end - start}%`;
    overlay.hidden = false;
    chart.dataset.chartSelection = `${low}:${high}`;
}

/** Émet `chart-range` : un composant Livewire ou Alpine l'écoute pour zoomer. */
function commit(chart, start, end) {
    const detail = { start, end, from: categoryOf(chart, start), to: categoryOf(chart, end) };
    const live = chart.querySelector("[data-chart-live]");

    if (live) {
        live.textContent = `Selected ${detail.from} to ${detail.to}.`;
    }

    chart.dispatchEvent(new CustomEvent("chart-range", { bubbles: true, detail }));
}

function onFocusOut(event) {
    const chart = event.target.closest?.(INTERACTIVE);

    if (chart && event.target === chart && !chart.contains(event.relatedTarget)) {
        setActive(chart, null);
    }
}

function onClick(event) {
    const toggle = event.target.closest?.("[data-chart-toggle]");

    if (toggle) {
        const chart = toggle.closest(INTERACTIVE);

        if (chart) {
            toggleSeries(chart, toggle);
        }

        return;
    }

    const exporter = event.target.closest?.("[data-chart-export]");

    if (exporter) {
        exportCsv(exporter);
    }
}

function toggleSeries(chart, button) {
    const key = button.dataset.chartToggle;
    const visible = button.getAttribute("aria-pressed") !== "false";
    const shown = chart.querySelectorAll('[data-chart-toggle][aria-pressed="true"]');

    // Toujours au moins une série visible : un chart vide n'apprend rien.
    if (visible && shown.length <= 1) {
        return;
    }

    button.setAttribute("aria-pressed", String(!visible));

    chart.querySelectorAll(`[data-series="${CSS.escape(key)}"]`).forEach((element) => {
        element.style.display = visible ? "none" : "";
    });

    chart.querySelectorAll('[data-slot="chart-bars"][data-stacked]').forEach(restack);
}

/**
 * Recolle les piles après avoir masqué une série : sans ça, la série
 * masquée laisserait un trou au milieu de chaque pile. L'échelle ne change
 * pas ; seules les positions des segments visibles sont recalculées, avec
 * la même règle que ChartHelper::bars().
 */
function restack(layer) {
    const min = Number(layer.dataset.scaleMin);
    const max = Number(layer.dataset.scaleMax);
    const radius = Number(layer.dataset.radius || 0);
    const horizontal = layer.hasAttribute("data-horizontal");
    const y = (value) => 100 - ((value - min) / (max - min || 1)) * 100;
    const stacks = new Map();

    layer.querySelectorAll("[data-index]").forEach((bar) => {
        if (bar.style.display === "none") {
            return;
        }

        const index = bar.dataset.index;

        stacks.set(index, [...(stacks.get(index) ?? []), bar]);
    });

    stacks.forEach((bars) => {
        let positive = 0;
        let negative = 0;
        let lastUp = null;
        let lastDown = null;

        bars.forEach((bar) => {
            const value = Number(bar.dataset.value);
            const from = value >= 0 ? positive : negative;
            const to = from + value;

            value >= 0 ? (positive = to) : (negative = to);
            value >= 0 ? (lastUp = bar) : (lastDown = bar);

            const top = y(Math.max(from, to));
            const size = Math.max(0, y(Math.min(from, to)) - top);

            if (horizontal) {
                bar.style.left = `${100 - top - size}%`;
                bar.style.width = `${size}%`;
            } else {
                bar.style.top = `${top}%`;
                bar.style.height = `${size}%`;
            }

            bar.style.borderRadius = "0";
        });

        const round = (bar, up) => {
            if (!bar) {
                return;
            }

            const r = `${radius}px`;

            bar.style.borderRadius = horizontal
                ? (up ? `0 ${r} ${r} 0` : `${r} 0 0 ${r}`)
                : (up ? `${r} ${r} 0 0` : `0 0 ${r} ${r}`);
        };

        round(lastUp, true);
        round(lastDown, false);
    });
}

/**
 * Exporte le tableau de données du chart. Les valeurs sont brutes
 * (`data-value`), pas mises en forme : 1250, pas « 1.3k ».
 */
function exportCsv(trigger) {
    const selector = trigger.dataset.chartExport;
    const chart = selector ? document.querySelector(selector) : trigger.closest('[data-slot="chart"]');
    const table = chart?.querySelector("table");

    if (!table) {
        return;
    }

    const lines = [...table.rows].map((row) =>
        [...row.cells].map((cell) => csvCell(cell.dataset.value ?? cell.textContent.trim())).join(","),
    );

    const blob = new Blob(["﻿" + lines.join("\r\n")], { type: "text/csv;charset=utf-8" });
    const link = document.createElement("a");

    link.href = URL.createObjectURL(blob);
    link.download = trigger.dataset.chartFilename || `${slug(chart.getAttribute("aria-label") || "chart")}.csv`;
    link.click();

    setTimeout(() => URL.revokeObjectURL(link.href), 0);
}

/**
 * Échappe une cellule. Un texte qui commence par =, +, -, @ serait lu
 * comme une formule par un tableur : on le neutralise. Un nombre, lui,
 * passe tel quel.
 */
function csvCell(value) {
    let text = String(value);

    if (/^[=+\-@\t\r]/.test(text) && !/^-?\d+(\.\d+)?$/.test(text)) {
        text = `'${text}`;
    }

    return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function slug(text) {
    return (
        text
            .toLowerCase()
            .normalize("NFD")
            .replace(/[̀-ͯ]/g, "")
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-|-$/g, "") || "chart"
    );
}
